// src/core/layer.css
var layer_default = '.fdk-layer {\n  position: fixed;\n  z-index: var(--fdk-z, 9100);\n  display: flex;\n  flex-direction: column;\n  gap: var(--fdk-sp-3);\n  padding: var(--fdk-sp-4);\n  pointer-events: none; /* la capa no bloquea clics\u2026 */\n  /*\n   * Sin max-width aqu\xED a prop\xF3sito: en las variantes `-center` esta capa fija\n   * `inset-inline: 0` (left:0 y right:0 a la vez). Si adem\xE1s hay un max-width, el ancho\n   * queda sobre-restringido y el navegador "gana" por el lado inicial (izquierda en LTR),\n   * recalculando `right` en vez de centrar \u2014 la capa termina anclada igual que `-start`.\n   * El l\xEDmite de ancho responsivo vive en el propio toast (ver src/toast/toast.css).\n   */\n}\n.fdk-layer > * { pointer-events: auto; } /* \u2026pero sus hijos s\xED */\n\n.fdk-layer--scoped { position: absolute; inset: 0; }\n.fdk-layer--top-start    { inset-block-start: 0; inset-inline-start: 0; align-items: flex-start; }\n.fdk-layer--top-center   { inset-block-start: 0; inset-inline: 0; align-items: center; }\n.fdk-layer--top-end      { inset-block-start: 0; inset-inline-end: 0; align-items: flex-end; }\n.fdk-layer--bottom-start { inset-block-end: 0; inset-inline-start: 0; align-items: flex-start; flex-direction: column-reverse; }\n.fdk-layer--bottom-center{ inset-block-end: 0; inset-inline: 0; align-items: center; flex-direction: column-reverse; }\n.fdk-layer--bottom-end   { inset-block-end: 0; inset-inline-end: 0; align-items: flex-end; flex-direction: column-reverse; }\n\n/* Fila `middle` \u2014 costados verticales centrados + centro exacto (ADR-003, nota de implementaci\xF3n). */\n.fdk-layer--middle-start  { inset-block: 0; inset-inline-start: 0; align-items: flex-start; justify-content: center; }\n.fdk-layer--middle-center { inset: 0; align-items: center; justify-content: center; }\n.fdk-layer--middle-end    { inset-block: 0; inset-inline-end: 0; align-items: flex-end; justify-content: center; }\n';

export {
  layer_default
};
